// Package agenttls pins remote agents' TLS certificates.
//
// Remote agents serve HTTPS with a self-signed certificate generated by the
// agent installer; its SHA-256 fingerprint (of the DER certificate) is
// reported at registration and stored on the server row. Every panel→agent
// connection over https verifies the peer certificate by exact fingerprint
// match: an agent URL without a stored fingerprint is refused (an unpinned
// self-signed certificate is never accepted), so a network attacker between
// the panel and a server cannot read the agent token or impersonate the agent.
package agenttls

import (
	"bytes"
	"context"
	"crypto/sha256"
	"crypto/subtle"
	"crypto/tls"
	"crypto/x509"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net"
	"net/http"
	"net/url"
	"strings"
	"sync"
	"time"
)

// Loader returns the pinned fingerprint for an agent address ("host:port",
// as dialed). An empty string means none is stored.
type Loader func(ctx context.Context, addr string) (string, error)

var (
	mu     sync.RWMutex
	loader Loader
)

// SetLoader installs the fingerprint lookup (the store sets it).
func SetLoader(l Loader) {
	mu.Lock()
	loader = l
	mu.Unlock()
}

// ErrNotPinned is returned for an https agent without a stored fingerprint.
var ErrNotPinned = errors.New("agent TLS certificate is not pinned for this server (re-register or update the agent)")

// Fingerprint returns the canonical fingerprint (lowercase hex SHA-256 of
// the DER certificate).
func Fingerprint(der []byte) string {
	sum := sha256.Sum256(der)
	return hex.EncodeToString(sum[:])
}

// Normalize accepts "AB:CD:..." or plain hex in any case and returns the
// canonical form, or "" when it is not a SHA-256 fingerprint.
func Normalize(fp string) string {
	s := strings.ToLower(strings.ReplaceAll(strings.TrimSpace(fp), ":", ""))
	s = strings.TrimPrefix(s, "sha256=")
	if len(s) != 64 {
		return ""
	}
	if _, err := hex.DecodeString(s); err != nil {
		return ""
	}
	return s
}

// PinVerifiedConfig returns a TLS config that accepts only a leaf
// certificate whose fingerprint equals pin. Chain and name checks are off
// (InsecureSkipVerify) because the agent's certificate is self-signed: the
// exact fingerprint check in VerifyConnection is the verification.
func PinVerifiedConfig(serverName, pin string) *tls.Config {
	want := Normalize(pin)
	return &tls.Config{
		ServerName:         serverName,
		MinVersion:         tls.VersionTLS12,
		InsecureSkipVerify: true, // replaced by the exact pin check below
		VerifyConnection: func(cs tls.ConnectionState) error {
			if want == "" {
				return ErrNotPinned
			}
			if len(cs.PeerCertificates) == 0 {
				return errors.New("agent presented no certificate")
			}
			got := Fingerprint(cs.PeerCertificates[0].Raw)
			if subtle.ConstantTimeCompare([]byte(got), []byte(want)) != 1 {
				return fmt.Errorf("agent TLS certificate does not match the pinned fingerprint (got %s)", got)
			}
			return nil
		},
	}
}

// DialFunc dials a plain TCP connection.
type DialFunc func(ctx context.Context, network, addr string) (net.Conn, error)

var defaultDialer = &net.Dialer{Timeout: 10 * time.Second, KeepAlive: 30 * time.Second}

// DialTLS wraps dial with the pinned TLS handshake for addr. Use it as
// http.Transport.DialTLSContext / websocket.Dialer.NetDialTLSContext.
func DialTLS(dial DialFunc) DialFunc {
	if dial == nil {
		dial = defaultDialer.DialContext
	}
	return func(ctx context.Context, network, addr string) (net.Conn, error) {
		mu.RLock()
		l := loader
		mu.RUnlock()
		if l == nil {
			return nil, ErrNotPinned
		}
		pin, err := l(ctx, addr)
		if err != nil {
			return nil, fmt.Errorf("look up agent TLS pin: %w", err)
		}
		if Normalize(pin) == "" {
			return nil, ErrNotPinned
		}
		host, _, err := net.SplitHostPort(addr)
		if err != nil {
			return nil, err
		}
		raw, err := dial(ctx, network, addr)
		if err != nil {
			return nil, err
		}
		conn := tls.Client(raw, PinVerifiedConfig(host, pin))
		if err := conn.HandshakeContext(ctx); err != nil {
			raw.Close()
			return nil, err
		}
		return conn, nil
	}
}

// Transport returns an http.Transport for agent calls: plain http as is,
// https only with the pinned certificate.
func Transport(dial DialFunc) *http.Transport {
	if dial == nil {
		dial = defaultDialer.DialContext
	}
	return &http.Transport{
		Proxy:                 nil,
		DialContext:           dial,
		DialTLSContext:        DialTLS(dial),
		ForceAttemptHTTP2:     false,
		MaxIdleConns:          50,
		IdleConnTimeout:       90 * time.Second,
		TLSHandshakeTimeout:   10 * time.Second,
		ExpectContinueTimeout: time.Second,
	}
}

// CertFingerprint returns the pin for a parsed certificate.
func CertFingerprint(cert *x509.Certificate) string { return Fingerprint(cert.Raw) }

// Upgrade switches a plain-http agent to TLS over the existing,
// token-authenticated connection: the agent creates its certificate and
// returns the fingerprint, then restarts with TLS. It returns the https URL
// and the fingerprint the caller must store (before the agent comes back).
//
// Trust is established on first use over that connection: an attacker able
// to tamper with it at this moment already holds the agent token (it travels
// in clear on http), so the switch is no weaker than what it replaces, and
// every later connection is pinned. Re-running the agent installer replaces
// the pin through registration.
func Upgrade(ctx context.Context, client *http.Client, agentURL, token, ip string) (newURL, fingerprint string, err error) {
	u, err := url.Parse(strings.TrimRight(agentURL, "/"))
	if err != nil || u.Scheme != "http" || u.Host == "" {
		return "", "", fmt.Errorf("agent URL is not a plain http URL")
	}
	if !InsecureTransport(u.String()) {
		return "", "", fmt.Errorf("the panel host's agent stays on loopback http")
	}
	body, _ := json.Marshal(map[string]string{"ip": ip})
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, u.String()+"/tasks/agent/tls/enable", bytes.NewReader(body))
	if err != nil {
		return "", "", err
	}
	req.Header.Set("Authorization", "Bearer "+token)
	req.Header.Set("Content-Type", "application/json")
	resp, err := client.Do(req)
	if err != nil {
		return "", "", err
	}
	defer resp.Body.Close()
	raw, _ := io.ReadAll(io.LimitReader(resp.Body, 64<<10))
	if resp.StatusCode == http.StatusNotFound {
		return "", "", ErrAgentTooOld
	}
	if resp.StatusCode != http.StatusOK {
		return "", "", fmt.Errorf("agent refused the TLS switch (HTTP %d): %s", resp.StatusCode, strings.TrimSpace(string(raw)))
	}
	var out struct {
		Fingerprint string `json:"fingerprint"`
	}
	if err := json.Unmarshal(raw, &out); err != nil {
		return "", "", fmt.Errorf("agent answer unreadable: %w", err)
	}
	fp := Normalize(out.Fingerprint)
	if fp == "" {
		return "", "", fmt.Errorf("agent returned no valid fingerprint")
	}
	u.Scheme = "https"
	return u.String(), fp, nil
}

// ErrAgentTooOld: the agent has no TLS switch (update it first).
var ErrAgentTooOld = errors.New("agent too old for the TLS switch; update the agent first")

// AddrOf returns the "host:port" an agent URL dials (default ports filled in).
func AddrOf(agentURL string) string {
	u, err := url.Parse(agentURL)
	if err != nil || u.Host == "" {
		return ""
	}
	port := u.Port()
	if port == "" {
		port = "80"
		if u.Scheme == "https" {
			port = "443"
		}
	}
	return net.JoinHostPort(strings.ToLower(u.Hostname()), port)
}

// InsecureTransport reports a non-loopback agent reached over plain http.
func InsecureTransport(agentURL string) bool {
	u, err := url.Parse(agentURL)
	if err != nil || u.Scheme != "http" {
		return false
	}
	h := u.Hostname()
	if strings.EqualFold(h, "localhost") {
		return false
	}
	ip := net.ParseIP(h)
	return ip == nil || !ip.IsLoopback()
}
